                    # Both non-zero, which one to use?
                    # Try: if different values, the combination might be wrong
                    if val_a != val_b:
                        continue  # Skip this pair
                    combined.append(val_a)
                elif val_a != 0:
                    combined.append(val_a)
                elif val_b != 0:
                    combined.append(val_b)
                else:
